<fieldset class="catalog-fields"><legend>2. Equipment identity</legend><div class="form-grid"><?php foreach(['category'=>['Category','category_id',null],'subcategory'=>['Subcategory','subcategory_id','category_id'],'type'=>['Equipment type','type_id','subcategory_id']] as $kind=>[$label,$field,$parent]):?><label><?= $label ?><select data-creatable="true" name="<?= $field ?>" data-catalog="<?= $kind ?>" <?= $parent?'data-parent-field="'.$parent.'"':'' ?>><option value="">Not specified</option><?php foreach($catalog[$kind] as $entry):?><option value="<?= e($entry['id']) ?>" data-name="<?= e($entry['name']) ?>" <?= $parent?'data-parent="'.e($entry[$parent]).'"':'' ?> <?= ($values[$field]??null)===$entry['id']?'selected':'' ?>><?= e($entry['name'].($entry['owner_id']?'   /  Company':'')) ?></option><?php endforeach;?></select></label><?php endforeach;?><label class="market-directory-field">OEM / manufacturer<select name="oem_id" data-market-directory="oem"><option value="">Search or create manufacturer</option><?php foreach($oems as $oem):?><option value="<?= e($oem['id']) ?>" <?= ($values['marketplace_oem_id']??'')===$oem['id']?'selected':'' ?>><?= e($oem['brand_name']) ?></option><?php endforeach;?></select><input type="hidden" name="new_oem"></label><label class="market-directory-field">OEM model<select name="oem_model_id" data-market-directory="model"><option value="">Search or create model</option><?php foreach($models as $model):?><option value="<?= e($model['id']) ?>" data-parent="<?= e($model['oem_id']) ?>" <?= ($values['marketplace_oem_model_id']??'')===$model['id']?'selected':'' ?>><?= e($model['model_name']) ?></option><?php endforeach;?></select><input type="hidden" name="new_model"></label><label class="full">Public specifications <small>One &quot;Label: Value&quot; per line</small><textarea name="specifications" rows="7" placeholder="Maximum pressure: 15,000 PSI&#10;Pump action: Double acting&#10;Flow capacity: 20 L/min"><?php $specSource=json_decode($listing['public_specifications']??$asset['marketplace_specifications']??'{}',true)?:[];foreach($specSource as $k=>$v)echo e($k.': '.$v)."\n";?></textarea></label></div></fieldset>
<fieldset><legend>3. Public listing</legend><div class="form-grid"><label>Listing title<input name="title" maxlength="255" required value="<?= mv($listing??[],[],'title',$asset['name']??'') ?>"></label><label>Purpose<select name="purpose" id="listing-purpose"><?php foreach(['LEASE'=>'For lease','SALE'=>'For sale','LEASE_OR_SALE'=>'Lease or sale'] as $v=>$l):?><option value="<?= $v ?>" <?= $purpose===$v?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select></label><label class="full">Commercial description<textarea name="description" rows="6" maxlength="10000" required><?= mv($listing??[],[],'description') ?></textarea></label><label>Marketplace status<select name="marketplace_status"><?php foreach(['AVAILABLE','RESERVED','MOBILIZING','IN_USE','MAINTENANCE','OFFLINE','BLOCKED'] as $status):?><option value="<?= $status ?>" <?= ($listing['marketplace_status']??'AVAILABLE')===$status?'selected':'' ?>><?= e(ucfirst(strtolower(str_replace('_',' ',$status)))) ?></option><?php endforeach;?></select></label><label>Visibility<select name="visibility"><option value="PUBLIC">Public</option><option value="NETWORK" <?= ($listing['visibility']??'')==='NETWORK'?'selected':'' ?>>Network only</option><option value="PRIVATE" <?= ($listing['visibility']??'')==='PRIVATE'?'selected':'' ?>>Private</option></select></label><label>Country<input name="country" maxlength="100" required value="<?= mv($listing??[],[],'country') ?>"></label><label>State / region<input name="state_region" maxlength="100" required value="<?= mv($listing??[],[],'state_region') ?>"></label><label>City<input name="city" maxlength="100" required value="<?= mv($listing??[],[],'city') ?>"></label><label>Available from<input type="date" name="available_from" value="<?= mv($listing??[],[],'available_from') ?>"></label><label>Pricing display<select name="price_visibility"><option value="REQUEST_QUOTE">Request quote</option><option value="PUBLIC" <?= ($listing['price_visibility']??'')==='PUBLIC'?'selected':'' ?>>Show public pricing</option></select></label><label>Compliance<select name="compliance_status"><?php foreach(['NOT_PROVIDED'=>'Not provided','AVAILABLE_ON_REQUEST'=>'Available on request','VALID'=>'Certification valid','EXPIRED'=>'Expired'] as $v=>$l):?><option value="<?= $v ?>" <?= ($listing['compliance_status']??'')===$v?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select></label><label class="check"><input type="checkbox" name="public_asset_code" value="1" <?= !empty($listing['public_asset_code'])?'checked':'' ?>> Show asset ID publicly</label></div></fieldset>
<fieldset data-terms="LEASE"><legend>4. Lease configuration</legend><div class="form-grid"><label>Duration unit<select name="duration_unit"><?php foreach(['HOUR'=>'Hour','DAY'=>'Day','WEEK'=>'Week','MONTH'=>'Month'] as $v=>$l):?><option value="<?= $v ?>" <?= $leaseUnit===$v?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select></label><label>Currency<input name="lease_currency" maxlength="3" value="<?= mv($lease,[],'currency','NGN') ?>"></label><label><span data-rate-label>Rate</span><input type="number" min="0" step="0.01" name="lease_rate" value="<?= e((string)$leaseRate) ?>"></label><label>Minimum duration<input type="number" min="1" name="minimum_duration" value="<?= mv($lease,[],'minimum_duration','1') ?>"></label><label>Security deposit<input type="number" min="0" step="0.01" name="security_deposit" value="<?= mv($lease,[],'security_deposit') ?>"></label><label class="check"><input type="checkbox" name="lease_negotiable" value="1" <?= !empty($lease['negotiable'])?'checked':'' ?>> Rate negotiable</label><label>Operator included<select name="operator_included"><option value="0">No</option><option value="1" <?= !empty($lease['operator_included'])?'selected':'' ?>>Yes</option></select></label><label data-show-when="operator_included:1"><span data-operator-rate-label>Operator rate</span><input type="number" min="0" step="0.01" name="operator_rate" value="<?= mv($lease,[],'operator_rate') ?>"></label><label>Consumables included<select name="consumables_included"><option value="0">No</option><option value="1" <?= !empty($lease['consumables_included'])||!empty($lease['fuel_included'])?'selected':'' ?>>Yes</option></select><small>Fuel, grease, oil, film, etc.</small></label><label data-show-when="consumables_included:1">Consumables details<input name="consumables_details" maxlength="500" value="<?= mv($lease,[],'consumables_details') ?>" placeholder="Fuel, grease, oil, film, etc."></label><?php foreach(['mobilization'=>['Mobilization terms','TO_BE_AGREED'],'demobilization'=>['Demobilization terms','TO_BE_AGREED'],'maintenance'=>['Maintenance responsibility','CASE_BY_CASE'],'insurance'=>['Insurance requirement','TO_BE_AGREED']] as $kind=>[$label,$default]):$value=$lease[$kind.'_option']??$default;?><label><?= $label ?><select name="<?= $kind ?>_option"><?php foreach(marketplace_term_options($kind) as $v=>$l):?><option value="<?= $v ?>" <?= $value===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach;?></select></label><label data-show-when="<?= $kind ?>_option:CUSTOM"><?= $label ?> details<textarea name="<?= $kind ?>_details" rows="3"><?= mv($lease,[],$kind.'_custom') ?></textarea></label><?php endforeach;?></div></fieldset>
<fieldset data-terms="SALE"><legend>5. Sale configuration</legend><div class="form-grid"><label>Currency<input name="sale_currency" maxlength="3" value="<?= mv($sale,[],'currency','NGN') ?>"></label><label>Asking price<input type="number" min="0" step="0.01" name="asking_price" value="<?= mv($sale,[],'asking_price') ?>"></label><label>Price negotiable<select name="sale_negotiable"><option value="0">No</option><option value="1" <?= !empty($sale['negotiable'])?'selected':'' ?>>Yes</option></select></label><label>Payment terms<select name="payment_terms"><?php foreach(marketplace_term_options('payment') as $v=>$l):?><option value="<?= $v ?>" <?= ($sale['payment_terms']??'TO_BE_AGREED')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach;?></select></label><label class="full" data-show-when="payment_terms:CUSTOM">Custom payment terms<textarea name="payment_terms_custom"><?= mv($sale,[],'payment_terms_custom') ?></textarea></label><label>Inspection required<select name="inspection_required"><option value="0">No</option><option value="1" <?= !isset($sale['inspection_allowed'])||$sale['inspection_allowed']?'selected':'' ?>>Yes</option></select></label><label>Sale condition<select name="sale_condition"><?php foreach(marketplace_term_options('sale_condition') as $v=>$l):?><option value="<?= $v ?>" <?= ($sale['condition']??'AS_IS')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach;?></select></label><label>Taxes / fees<select name="taxes_fees"><?php foreach(marketplace_term_options('taxes') as $v=>$l):?><option value="<?= $v ?>" <?= ($sale['taxes_fees']??'TO_BE_AGREED')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach;?></select></label><label class="full">Custom terms / notes<textarea name="sale_notes"><?= mv($sale,[],'sale_notes') ?></textarea></label></div></fieldset>
<fieldset><legend>6. Geographic availability</legend><p data-location-empty>No geographic restrictions &mdash; equipment can be mobilized anywhere.</p><div class="location-rule-builder"><label>Search global locations<input type="search" id="market-location-search" autocomplete="off" placeholder="Country, state / province / region, or city"></label><div class="location-search-results" id="market-location-results" role="listbox" hidden></div><div class="location-rule-actions" hidden><button type="button" data-location-rule="ALLOW">+ Allow location</button><button type="button" data-location-rule="RESTRICT">- Restrict location</button></div><div class="location-chips" aria-live="polite"></div><input type="hidden" name="location_rules" value="<?= e(json_encode($locationRules)) ?>"></div></fieldset>
<fieldset><legend>7. Approved public media</legend><p>At least one public image is required to publish. Internal photos and documents remain private unless you explicitly add them here.</p><div class="form-grid"><label>Upload image or PDF<input type="file" name="media" accept="image/jpeg,image/png,image/webp,application/pdf"></label><label>Media type<select name="media_type"><option value="OTHER">Other document</option><option value="SPECIFICATION_SHEET">Specification sheet</option><option value="BROCHURE">Brochure</option><option value="CERTIFICATE">Certificate</option><option value="INSPECTION">Inspection</option></select></label><label>Media title<input name="media_title" maxlength="255"></label><label>Visibility<select name="media_visibility"><option value="PUBLIC">Public</option><option value="ON_REQUEST">On request</option><option value="PRIVATE">Private</option></select></label></div><?php if($listing):$media=rows('SELECT * FROM marketplace_listing_media WHERE listing_id=? ORDER BY is_primary DESC,sequence',[$id]);$privatePhotos=rows('SELECT p.id,p.caption FROM equipment_photos p WHERE p.equipment_id=? AND NOT EXISTS(SELECT 1 FROM marketplace_listing_media m WHERE m.listing_id=? AND m.equipment_photo_id=p.id)',[$asset['id'],$id]);?><div class="media-list"><?php foreach($media as $item):?><span><?= e($item['title']?:$item['media_type']) ?>   /  <?= e($item['visibility']) ?></span><?php endforeach;?></div><?php endif;?></fieldset>
<div class="form-actions"><button class="market-button">Save and preview</button><a href="marketplace-manage?view=listings">Cancel</a></div></form>
<?php if($listing&&$privatePhotos):?><section class="manage-table"><h2>Publish an existing ERP photo</h2><p>Each selection is explicit. Unselected photos remain private.</p><?php foreach($privatePhotos as $photo):?><form action="marketplace-action" method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="media.link"><input type="hidden" name="id" value="<?= e($id) ?>"><input type="hidden" name="equipment_photo_id" value="<?= e($photo['id']) ?>"><button>Publish <?= e($photo['caption']?:'equipment photo') ?></button></form><?php endforeach;?></section><?php endif;?>
<script type="application/json" id="marketplace-edit-data"><?= json_encode(['compliance'=>['certification_type'=>$listing['certification_type']??'','certification_valid_until'=>$listing['certification_valid_until']??'','last_inspected_on'=>$listing['last_inspected_on']??''],'periods'=>$listing?rows('SELECT id,start_date,end_date,availability,note FROM marketplace_availability_periods WHERE listing_id=? ORDER BY start_date',[$id]):[],'locations'=>marketplace_locations()],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script><script src="assets/js/equipment-catalog.js?v=<?= filemtime(__DIR__.'/assets/js/equipment-catalog.js') ?>" defer></script><script src="assets/js/marketplace-manage.js?v=<?= filemtime(__DIR__.'/assets/js/marketplace-manage.js') ?>" defer></script>
<?php else:?><section class="market-empty"><h1>Page not found</h1></section><?php endif;require __DIR__.'/includes/operations-footer.php';?>
